.od-disclosure--flat:is(:not([open]),[open])>summary:hover{background:var(--od-muted);border-radius:var(--radius-control)}
.od-segmented{display:flex;width:max-content;max-width:100%;gap:2px;padding:3px;background:var(--od-muted);border:1px solid var(--od-input-border);border-radius:var(--radius-surface)}
.od-segmented>button{min-height:32px;border-radius:var(--radius-control)}

/* Collapsible rows are interactive controls, including nested technical details. */
@media(pointer:coarse){.od-disclosure>summary{min-height:44px}}

